"""
    Converts a redshift to a scale factor.

    :param redshift: redshift of the object
    :type redshift: float or ndarray

    :return: scale factor
    :rtype: float or ndarray
    """
def scaleFromRedshift(redshift: Any) -> object {
    return (1.0 / (redshift + 1.0));
}

"""
        Returns the distance between two points.
    """
def getDistance(origin: Any, point: Any) -> object {
    dist = (((origin[0] - point[0]) ** 2) + ((origin[1] - point[1]) ** 2)) ** 0.5;
    return dist;
}

"""Custom Parse Type to parse a boolean value.

    The same values are parsed as YAML does:
        http://yaml.org/type/bool.html

    Plus 0 and 1
    """
def boolean_type(text: Any) -> object {
    text = text.lower();
    return (
        (text == "1") or text.startswith("y") or (text == "true") or (text == "on")
    );
}

"""
    Calculates the mean of a list of numbers
    :param args: List of numbers
    :return:  The mean of a list of numbers
    """
def mean(*args: Any) -> object {
    index = 0;
    sum_index = 0;
    for i in args {
        index += 1;
        sum_index += float(i);
    }
    return (sum_index / index) if (index != 0) else "Division by zero";
}

""" List of indices into the RTTOV chanprof(:) array corresponding to the chanlist.
        NB This assumes you've checked the chanlist against chanprof already.
    """
def getChanprofIndex(chanprof: Any, profile: Any, chanList: Any) -> object {
    ilo = sum(map(len, chanprof[:(profile - 1)]));
    ichanprof = [];
    for c in chanList {
        ichanprof.append((ilo + chanprof[(profile - 1)].index(c)));
    }
    return ichanprof;
}
